1	import Foundation
2	import Observation
3	import ReachyKit
4	
5	/// Phase 0.4 spike: manual connect + state-stream counter with live frequency.
6	@MainActor
7	@Observable
8	final class SpikeModel {
9	    var host: String = UserDefaults.standard.string(forKey: "lastHost") ?? "127.0.0.1" {
10	        didSet { UserDefaults.standard.set(host, forKey: "lastHost") }
11	    }
12	
13	    private(set) var handshakeSummary: String?
14	    private(set) var lastError: String?
15	    private(set) var isStreaming = false
16	    private(set) var frameCount = 0
17	    private(set) var hertz: Double = 0
18	    private(set) var streamDiagnostics = StateStreamDiagnostics()
19	
20	    var invalidFrameCount: Int {
21	        streamDiagnostics.decodeFailures + streamDiagnostics.unsupportedFrames
22	    }
23	
24	    private var streamTask: Task<Void, Never>?
25	    private var arrivals: [ContinuousClock.Instant] = []
26	
27	    func connect() async {
28	        lastError = nil
29	        handshakeSummary = nil
30	        guard let address = RobotAddress(parsing: host) else {
31	            lastError = "Invalid address: \(host)"
32	            return
33	        }
34	        do {
35	            let connection = try RobotConnection(address: address)
36	            let handshake = try await connection.handshake()
37	            handshakeSummary = """
38	            name: \(handshake.identity.name ?? "—")
39	            daemon: \(handshake.identity.daemonVersion ?? "—")
40	            hardware: \(handshake.identity.hardwareID ?? "— (sim)")
41	            state: \(handshake.status.state)
42	            sim: \(handshake.status.simulationEnabled?.description ?? "—")
43	            """
44	        } catch {
45	            lastError = "\(error)"
46	        }
47	    }
48	
49	    func toggleStream() {
50	        if isStreaming {
51	            streamTask?.cancel()
52	            streamTask = nil
53	            isStreaming = false
54	            return
55	        }
56	        guard let address = RobotAddress(parsing: host) else {
57	            lastError = "Invalid address: \(host)"
58	            return
59	        }
60	        do {
61	            let client = try StateStreamClient(address: address)
62	            frameCount = 0
63	            arrivals = []
64	            streamDiagnostics = .init()
65	            isStreaming = true
66	            streamTask = Task { [weak self] in
67	                for await update in client.updates() {
68	                    guard let self else { break }
69	                    streamDiagnostics = update.diagnostics
70	                    if update.state != nil {
71	                        recordFrame()
72	                    }
73	                }
74	            }
75	        } catch {
76	            lastError = "\(error)"
77	        }
78	    }
79	
80	    private func recordFrame() {
81	        frameCount += 1
82	        let now = ContinuousClock.now
83	        arrivals.append(now)
84	        // Sliding 2-second window; rate over the actual observed span
85	        arrivals.removeAll { $0 < now - .seconds(2) }
86	        if let first = arrivals.first, arrivals.count >= 2 {
87	            let span = first.duration(to: now)
88	            let seconds = Double(span.components.seconds) + Double(span.components.attoseconds) / 1e18
89	            if seconds > 0 {
90	                hertz = Double(arrivals.count - 1) / seconds
91	            }
92	        }
93	    }
94	}
